// Personal campaign intelligence. No automatic eligibility or source verification.
export const CAMPAIGN_STATUS={unknown:'Belum diketahui',rumor:'Rumor',speculative:'Spekulatif',confirmed:'Diumumkan',live:'Berlangsung',ended:'Berakhir'};
export const TASK_STATUS={pending:'Belum dikerjakan',done:'Selesai · pribadi',failed:'Gagal / terhambat',verify:'Butuh verifikasi'};
const text=(v,n)=>typeof v==='string'?v.trim().slice(0,n):'';
export function dateOnly(v){if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v))return '';const d=new Date(v+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===v?v:''}
export function sourceURL(v){v=text(v,500);if(!v)return '';const u=new URL(v);if(u.protocol!=='https:'||u.username||u.password)throw Error('Gunakan URL HTTPS tanpa kredensial.');return u.href}
export function cleanCampaign(raw={}){raw=raw&&typeof raw==='object'?raw:{};return {status:Object.hasOwn(CAMPAIGN_STATUS,raw.status)?raw.status:'unknown',deadline:dateOnly(raw.deadline),snapshot:dateOnly(raw.snapshot),source:sourceURL(raw.source),contract:sourceURL(raw.contract),channel:sourceURL(raw.channel),difficulty:['unknown','beginner','intermediate','advanced'].includes(raw.difficulty)?raw.difficulty:'unknown',gasUSD:raw.gasUSD!==''&&raw.gasUSD!=null&&Number.isFinite(Number(raw.gasUSD))&&Number(raw.gasUSD)>=0?Math.min(Number(raw.gasUSD),1e6):null,reward:text(raw.reward,200),requirements:text(raw.requirements,1000),checkedAt:dateOnly(raw.checkedAt),changes:(Array.isArray(raw.changes)?raw.changes:[]).filter(e=>typeof e?.at==='string'&&Number.isFinite(Date.parse(e.at))&&typeof e?.summary==='string').slice(-20).map(e=>({at:new Date(e.at).toISOString(),summary:text(e.summary,500)}))}}
export function cleanCampaigns(raw,ids){const result={};for(const id of ids){try{result[id]=cleanCampaign(raw?.[id])}catch{result[id]=cleanCampaign()}}return result}
export function updateCampaign(current,data,now=new Date()){const next=cleanCampaign({...data,changes:current.changes});if(next.status!=='unknown'&&!next.source)throw Error('Catat sumber pengumuman untuk status kampanye yang Anda pilih.');if((next.deadline||next.snapshot)&&!next.source)throw Error('Tanggal kampanye memerlukan URL sumber aturan.');const changed=Object.keys(next).filter(k=>k!=='changes'&&next[k]!==current[k]);if(!changed.length)return current;return {...next,changes:[...current.changes,{at:now.toISOString(),summary:changed.join(', ')}].slice(-20)}}
export function cleanTaskStates(raw,projects,done){const out={};for(const p of projects)for(let i=0;i<p.tasks.length;i++){const key=p.id+':'+i;if(done[key])out[key]='done';else if(['failed','verify'].includes(raw?.[key]))out[key]=raw[key]}return out}
export function filterDirectory(projects,state,filters={}){const list=projects.filter(p=>{const c=state.campaigns[p.id];return (!filters.status||filters.status==='all'||c.status===filters.status)&&(!filters.kind||filters.kind==='all'||p.kind===filters.kind)&&(!filters.difficulty||filters.difficulty==='all'||c.difficulty===filters.difficulty)&&(!filters.cost||filters.cost==='all'||(filters.cost==='unknown'?c.gasUSD===null:c.gasUSD!==null&&(filters.cost==='zero'?c.gasUSD===0:c.gasUSD<=5)))});if(filters.sort==='deadline')list.sort((a,b)=>(state.campaigns[a.id].deadline||'9999').localeCompare(state.campaigns[b.id].deadline||'9999'));if(filters.sort==='cost')list.sort((a,b)=>(state.campaigns[a.id].gasUSD??Infinity)-(state.campaigns[b.id].gasUSD??Infinity));return list}
export function radarEvents(projects,state,now=new Date()){const today=new Date(now.getFullYear(),now.getMonth(),now.getDate());const out=[];for(const p of projects){const r=state.records[p.id],c=state.campaigns[p.id];if(!state.saved.includes(p.id)||['completed','archived'].includes(r.status))continue;for(const [kind,date,label] of [['deadline',c.deadline,'Tenggat kampanye · catatan sumber'],['snapshot',c.snapshot,'Snapshot · catatan sumber'],['personal',r.due,'Target riset pribadi']]){if(!date)continue;const days=Math.round((new Date(date+'T00:00:00').getTime()-today.getTime())/86400000);if(days>7||days< -30)continue;const id=p.id+':'+kind+':'+date;out.push({id,project:p,kind,date,label,days,read:state.radarRead.includes(id),source:kind==='personal'?'':c.source})}}return out.sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id))}
export function campaignCalendar(p,c,now=new Date()){const esc=v=>String(v).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Airdrop Museum//Campaign Radar//ID',...[['deadline',c.deadline,'Campaign deadline'],['snapshot',c.snapshot,'Snapshot date']].filter(([,date])=>date).flatMap(([kind,date,label])=>['BEGIN:VEVENT',`UID:${esc(p.id)}-${kind}-${date}@airdrop-museum`,`DTSTAMP:${now.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART;VALUE=DATE:${date.replaceAll('-','')}`,`SUMMARY:${esc(p.name+' — '+label)}`,`DESCRIPTION:${esc('Personal source record, not independently verified. '+c.source)}`,'END:VEVENT']),'END:VCALENDAR'].join('\r\n')}
